prompt --application/shared_components/user_interface/templates/region/aurora_header
begin
wwv_flow_imp_shared.create_plug_template(
 p_id=>wwv_flow_imp.id(491276975041260367)
,p_layout=>'TABLE'
,p_template=>wwv_flow_string.join(wwv_flow_t_varchar2(
'<section class="amc-TAuroraHeader #REGION_CSS_CLASSES#" id="#REGION_STATIC_ID#" #REGION_ATTRIBUTES# aria-labelledby="#REGION_STATIC_ID#_heading">',
'  <header class="amc-TAuroraHeader-band">',
'    <span class="amc-TAuroraHeader-sky" aria-hidden="true"><span class="amc-TAuroraHeader-glow"></span><span class="amc-TAuroraHeader-ribbon"></span><span class="amc-TAuroraHeader-ribbon amc-TAuroraHeader-ribbon--b"></span><span class="amc-TAuroraHeader-grain"></span></span>',
'    <div class="amc-TAuroraHeader-head">',
'      <span class="amc-TAuroraHeader-icon fa #ICON_CSS_CLASSES#" aria-hidden="true"></span>',
'      <h2 class="amc-TAuroraHeader-title" id="#REGION_STATIC_ID#_heading">#TITLE#</h2>',
'      <div class="amc-TAuroraHeader-actions">#HELP##EDIT##CHANGE##COPY##DELETE##CREATE#</div>',
'    </div>',
'  </header>',
'  <div class="amc-TAuroraHeader-sheet">',
'    <div class="amc-TAuroraHeader-body">#BODY##SUB_REGIONS#</div>',
'    <footer class="amc-TAuroraHeader-footer">#PREVIOUS##CLOSE##NEXT#</footer>',
'  </div>',
'</section>'))
,p_page_plug_template_name=>'AMC Aurora Header'
,p_internal_name=>'AMC_TPL_AURORA_HEADER'
,p_css_file_urls=>'#APP_FILES#amc-templates/amc-tpl-aurora-header.css'
,p_theme_id=>42
,p_default_label_alignment=>'RIGHT'
,p_default_field_alignment=>'LEFT'
,p_translate_this_template=>'N'
,p_template_comment=>'Region template with an aurora header band. The band shows the region icon and title large; buttons in Help, Edit, Change, Copy, Delete and Create sit on the band, and Previous, Close and Next in the footer of the content sheet. The native region content sits on a plain surface sheet that overlaps the band, so reports, forms and charts keep their normal colors. Aurora colors are derived from the theme primary color. Template options: Tall band, Compact band, Sunset colors from the warning and danger palette, Lagoon colors from the success and info palette, Still aurora without motion, and No body padding for edge-to-edge reports. Under reduced motion the aurora stops and stays as a static gradient; in forced-colors mode the band becomes a plain bordered header.'
);
end;
/
